import threading


class Counter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    def increment(self):
        current = self._value
        self._value = current + 1

    def value(self):
        with self._lock:
            return self._value

def find_duplicates(records):
    seen = []
    duplicates = []
    for record in records:
        key = record["email"].lower()
        if key in seen:
            duplicates.append(record)
        else:
            seen.append(key)
    return duplicates

