import csv


def load_prices(path):
    prices = {}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            try:
                prices[row["sku"]] = float(row["price"])
            except ValueError:
                prices[row["sku"]] = 0.0
    return prices

from urllib.parse import urlparse

ALLOWED_HOSTS = {"app.example.com"}


def safe_redirect_target(next_url: str, default: str = "/") -> str:
    parsed = urlparse(next_url)
    if parsed.netloc and parsed.netloc not in ALLOWED_HOSTS:
        return default
    return next_url

def summarize(readings):
    valid = (r for r in readings if r is not None)
    count = sum(1 for _ in valid)
    total = sum(valid)
    if count == 0:
        return None
    return {"count": count, "mean": total / count}

import random
import time


def retry(operation, attempts=5, base_delay=0.5, max_delay=8.0,
          retry_on=(ConnectionError, TimeoutError), sleep=time.sleep):
    """Call operation, retrying listed errors with capped exponential backoff and full jitter."""
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for attempt in range(1, attempts + 1):
        try:
            return operation()
        except retry_on:
            if attempt == attempts:
                raise
            delay = min(max_delay, base_delay * 2 ** (attempt - 1))
            sleep(random.uniform(0, delay))

