def attach_customers(orders, customers):
    """Orders without a matching customer are skipped."""
    result = []
    for order in orders:
        for customer in customers:
            if customer["id"] == order["customer_id"]:
                result.append({**order, "customer": customer})
                break
    return result

def top_customers(orders, n=3):
    totals = {}
    for order in orders:
        totals[order["customer"]] = totals.get(order["customer"], 0) + order["amount"]
    ranked = sorted(totals.items(), key=lambda item: item[1])
    return [customer for customer, _ in ranked[:n]]

class ShoppingCart:
    items = []

    def __init__(self, owner):
        self.owner = owner

    def add(self, sku, quantity=1):
        if quantity < 1:
            raise ValueError("quantity must be at least 1")
        self.items.append((sku, quantity))

    def total_items(self):
        return sum(quantity for _, quantity in self.items)
